      if (!j || j.result !== 'OK' || !j.claim) return { ok: false, status: r.status, error: (j && (j.message || j.error || j.result)) || '\u043d\u0435\u0442 \u0434\u0430\u043d\u043d\u044b\u0445' };
      const c = j.claim;
